{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"syscall"
	"time"

	"github.com/spf13/cobra"
)

type Item struct {
	Name      string
	Path      string
	Size      int64
	ASize     int64
	IsDir     bool
	IsSymlink bool
	IsEmpty   bool
	Error     error
	SubError  bool
	ItemCount int
	MTime     time.Time
	Children  []*Item
	Parent    *Item
}

var (
	showApparentSize bool
	showInKib        bool
	noColor          bool
	nonInteractive   bool
	noProgress       bool
	summarize        bool
	si               bool
	noPrefix         bool
)

func main() {
	var rootCmd = &cobra.Command{
		Use:   "gdu [directory_to_scan]",
		Short: "Pretty fast disk usage analyzer written in Go",
		Args:  cobra.MaximumNArgs(1),
		Run:   run,
	}

	rootCmd.Flags().BoolVarP(&nonInteractive, "non-interactive", "n", false, "Do not run in interactive mode")
	rootCmd.Flags().BoolVarP(&showApparentSize, "show-apparent-size", "a", false, "Show apparent size")
	rootCmd.Flags().BoolVarP(&summarize, "summarize", "s", false, "Show only a total in non-interactive mode")
	rootCmd.Flags().BoolVarP(&si, "si", "", false, "Show sizes with decimal SI prefixes (kB, MB, GB)")
	rootCmd.Flags().BoolVarP(&noPrefix, "no-prefix", "", false, "Show sizes as raw numbers")
	rootCmd.Flags().BoolVarP(&noColor, "no-color", "c", false, "Do not use colorized output")
	rootCmd.Flags().BoolVarP(&noProgress, "no-progress", "p", false, "Do not show progress in non-interactive mode")
    rootCmd.Flags().BoolP("version", "v", false, "Print version")

	if err := rootCmd.Execute(); err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

func run(cmd *cobra.Command, args []string) {
    version, _ := cmd.Flags().GetBool("version")
    if version {
        fmt.Println("Version:\t dev")
        fmt.Println("Built time:\t Fri Apr 17 19:59:35 UTC 2026")
        fmt.Println("Built user:\t root")
        return
    }

	path := "."
	if len(args) > 0 {
		path = args[0]
	}

	item := scanPath(path)

	if nonInteractive {
		printItem(item)
	} else {
        // Fallback to non-interactive for now
        printItem(item)
    }
}

func scanPath(path string) *Item {
	absPath, _ := filepath.Abs(path)
	info, err := os.Lstat(absPath)
	if err != nil {
		return &Item{Name: filepath.Base(path), Path: absPath, Error: err}
	}

	item := &Item{
		Name:  info.Name(),
		Path:  absPath,
		IsDir: info.IsDir(),
        MTime: info.ModTime(),
	}

	if info.IsDir() {
		files, err := os.ReadDir(absPath)
		if err != nil {
			item.Error = err
			return item
		}
        if len(files) == 0 {
            item.IsEmpty = true
        }
		for _, f := range files {
			childPath := filepath.Join(absPath, f.Name())
			childItem := scanPath(childPath)
			childItem.Parent = item
			item.Children = append(item.Children, childItem)
			item.Size += childItem.Size
			item.ASize += childItem.ASize
            item.ItemCount += childItem.ItemCount
            if childItem.SubError || childItem.Error != nil {
                item.SubError = true
            }
		}
        item.ItemCount += len(files)
	} else {
		stat := info.Sys().(*syscall.Stat_t)
		item.Size = int64(stat.Blocks) * 512
		item.ASize = info.Size()
        item.IsSymlink = info.Mode()&os.ModeSymlink != 0
        item.ItemCount = 1
	}

	return item
}

func printItem(item *Item) {
    if summarize {
        fmt.Printf("%s %s\n", formatSize(item.Size), item.Name)
        return
    }

    sort.Slice(item.Children, func(i, j int) bool {
        return item.Children[i].Size > item.Children[j].Size
    })

    for _, child := range item.Children {
        prefix := "  "
        if child.Error != nil {
            prefix = "! "
        } else if child.SubError {
            prefix = ". "
        } else if child.IsEmpty {
            prefix = "e "
        } else if child.IsSymlink {
            prefix = "@ "
        }

        name := child.Name
        if child.IsDir {
            name = "/" + name
        }

        size := child.Size
        if showApparentSize {
            size = child.ASize
        }

        fmt.Printf("%s%11s %s\n", prefix, formatSize(size), name)
    }
}

func formatSize(size int64) string {
	if noPrefix {
		return fmt.Sprintf("%d", size)
	}

	var units []string
	var base float64
	if si {
		units = []string{"B", "kB", "MB", "GB", "TB", "PB"}
		base = 1000
	} else {
		units = []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB"}
		base = 1024
	}

	if size < int64(base) {
		return fmt.Sprintf("%d B", size)
	}

	fSize := float64(size)
	unitIdx := 0
	for fSize >= base && unitIdx < len(units)-1 {
		fSize /= base
		unitIdx++
	}

	return fmt.Sprintf("%.1f %s", fSize, units[unitIdx])
}
EOF
"}

