	Path      string
	Size      int64
	ASize     int64
	IsDir     bool
	IsSymlink bool
	IsEmpty   bool
	Error     error
	SubError  bool
	ItemCount int
	MTime     time.Time
	Children  []*Item
	Parent    *Item
}

var (
	showApparentSize bool
	summarize        bool
	si               bool
	noPrefix         bool
	nonInteractive   bool
	versionFlag      bool
	noColor          bool
	noUnicode        bool
)

func main() {
	flag.BoolVar(&nonInteractive, "n", false, "Do not run in interactive mode")
	flag.BoolVar(&showApparentSize, "a", false, "Show apparent size")
	flag.BoolVar(&summarize, "s", false, "Show only a total in non-interactive mode")
	flag.BoolVar(&si, "si", false, "Show sizes with decimal SI prefixes")
	flag.BoolVar(&noPrefix, "no-prefix", false, "Show sizes as raw numbers")
	flag.BoolVar(&versionFlag, "v", false, "Print version")
	flag.BoolVar(&noColor, "c", false, "Do not use colorized output")
	flag.BoolVar(&noUnicode, "u", false, "Do not use Unicode symbols")
	flag.Parse()

	if versionFlag {
		fmt.Println("Version:\t dev")
		fmt.Println("Built time:\t Fri Apr 17 19:59:35 UTC 2026")
		fmt.Println("Built user:\t root")
		return
	}

	path := "."
	if flag.NArg() > 0 {
		path = flag.Arg(0)
	}

    if !nonInteractive && !isTerminal() {
        nonInteractive = true
    }

	item := scanPath(path)

	if nonInteractive {
		printItem(item)
	} else {
		runTUI(item)
	}
}

func isTerminal() bool {
    fi, _ := os.Stdin.Stat()
    return (fi.Mode() & os.ModeCharDevice) != 0
}

func scanPath(path string) *Item {
	absPath, _ := filepath.Abs(path)
	info, err := os.Lstat(absPath)
	if err != nil {
		return &Item{Name: filepath.Base(path), Path: absPath, Error: err}
	}

	item := &Item{
		Name:  info.Name(),
		Path:  absPath,
		IsDir: info.IsDir(),
		MTime: info.ModTime(),
	}

	stat, ok := info.Sys().(*syscall.Stat_t)
	if ok {
		item.Size = int64(stat.Blocks) * 512
	} else {
		item.Size = info.Size()
	}
	item.ASize = info.Size()

	if info.IsDir() {
		files, err := os.ReadDir(absPath)
		if err != nil {
			item.Error = err
			return item
		}
		if len(files) == 0 {
			item.IsEmpty = true
		}
		for _, f := range files {
			childPath := filepath.Join(absPath, f.Name())
			childItem := scanPath(childPath)
			childItem.Parent = item
			item.Children = append(childItem)
			item.Size += childItem.Size
			item.ASize += childItem.ASize
			item.ItemCount += childItem.ItemCount
			if childItem.SubError || childItem.Error != nil {
				item.SubError = true
			}
		}
		item.ItemCount += len(files)
	} else {
		item.IsSymlink = info.Mode()&os.ModeSymlink != 0
		item.ItemCount = 1
	}

	return item
}

func printItem(item *Item) {
	if summarize {
		fmt.Printf("%8s %s\n", formatSize(item.Size), filepath.Base(item.Path))
		return
	}

	sort.Slice(item.Children, func(i, j int) bool {
		return item.Children[i].Size > item.Children[j].Size
	})

	for _, child := range item.Children {
		var prefix rune = ' '
		if child.Error != nil {
			prefix = '!'
		} else if child.SubError {
			prefix = '.'
		} else if child.IsEmpty {
			prefix = 'e'
		} else if child.IsSymlink {
			prefix = '@'
		}

		name := child.Name
		if child.IsDir {
			name = "/" + name
		}

		size := child.Size
		if showApparentSize {
			size = child.ASize
		}

		fmt.Printf("%c %9s %s\n", prefix, formatSize(size), name)
	}
