		base = 1000
	} else {
		units = []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB"}
		base = 1024
	}

	if size < int64(base) && size >= 0 {
		return fmt.Sprintf("%d B", size)
	}

	fSize := float64(size)
	unitIdx := 0
	for fSize >= base && unitIdx < len(units)-1 {
		fSize /= base
		unitIdx++
	}

	return fmt.Sprintf("%.1f %s", fSize, units[unitIdx])
}

func runTUI(rootItem *Item) {
    // Basic TUI implementation
    // Set terminal to raw mode
    exec.Command("stty", "-F", "/dev/tty", "cbreak", "min", "1").Run()
    exec.Command("stty", "-F", "/dev/tty", "-echo").Run()
    defer exec.Command("stty", "-F", "/dev/tty", "sane").Run()

    currentItem := rootItem
    selectedIndex := 0

    for {
        draw(currentItem, selectedIndex)

        var b [1]byte
        os.Stdin.Read(b[:])

        switch b[0] {
        case 'q':
            return
        case 27: // ESC
            // Handle arrow keys
            var b2 [2]byte
            os.Stdin.Read(b2[:])
            if b2[0] == '[' {
                switch b2[1] {
                case 'A': // Up
                    if selectedIndex > 0 {
                        selectedIndex--
                    }
                case 'B': // Down
                    if selectedIndex < len(currentItem.Children)-1 {
                        selectedIndex++
                    }
                }
            }
        }
    }
}

func draw(item *Item, selectedIndex int) {
    fmt.Print("\033[H\033[2J") // Clear screen
    fmt.Printf(" gdu ~ Use arrow keys to navigate, press ? for help\n")
    fmt.Printf(" --- %s ---\n", item.Path)

