        prefix := "  "
        if i == selectedIndex {
            prefix = "> "
        }

        name := child.Name
        if child.IsDir {
            name = "/" + name
        }

        size := child.Size
        if showApparentSize {
            size = child.ASize
        }

        // Simple bar
        total := item.Size
        if showApparentSize { total = item.ASize }
        percent := float64(size) / float64(total)
        bar := drawBar(percent)

        fmt.Printf("%s%9s %s %s\n", prefix, formatSize(size), bar, name)
    }

    fmt.Printf("\n Total disk usage: %s Apparent size: %s Items: %d Sorting by: %s\n",
        formatSize(item.Size), formatSize(item.ASize), item.ItemCount, sortBy)
}

func drawBar(percent float64) string {
    if noUnicode {
        width := 10
        full := int(percent * float64(width))
        res := "["
        for i := 0; i < width; i++ {
            if i < full { res += "#" } else { res += " " }
        }
        res += "]"
        return res
    }
    // Unicode bar logic
    blocks := []string{" ", "▏", "▎", "▍", "▌", "▋", "▊", "▉", "█"}
    width := 10
    totalBlocks := percent * float64(width)
    fullBlocks := int(totalBlocks)
    res := ""
    for i := 0; i < fullBlocks; i++ {
        res += "█"
    }
    if fullBlocks < width {
        remainder := int((totalBlocks - float64(fullBlocks)) * 8)
        res += blocks[remainder]
        for i := fullBlocks + 1; i < width; i++ {
            res += " "
        }
    }
    res += "▏"
    return res
}
