func stringsSplit(s, sep string) []string {
    var res []string
    start := 0
    for i := 0; i < len(s); i++ {
        if s[i:i+len(sep)] == sep {
            res = append(res, s[start:i])
            start = i + len(sep)
            i += len(sep) - 1
        }
    }
    res = append(res, s[start:])
    return res
}

func printItem(item *Item) {
	if summarize {
