        case "itemCount":
            return items[i].ItemCount > items[j].ItemCount
        case "mtime":
            return items[i].MTime.After(items[j].MTime)
        default: // size
            s1 := items[i].Size
            s2 := items[j].Size
            if showApparentSize {
                s1 = items[i].ASize
                s2 = items[j].ASize
            }
            if s1 == s2 {
                return items[i].Name < items[j].Name
            }
            return s1 > s2
        }
    })
}

func formatSize(size int64) string {
	if noPrefix {
		return fmt.Sprintf("%d", size)
	}

	var units []string
	var base float64
	if si {
		units = []string{"B", "kB", "MB", "GB", "TB", "PB"}
		base = 1000
	} else {
		units = []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB"}
		base = 1024
	}

	if size < int64(base) && size >= 0 {
		return fmt.Sprintf("%d B", size)
	}

	fSize := float64(size)
	unitIdx := 0
	for fSize >= base && unitIdx < len(units)-1 {
		fSize /= base
		unitIdx++
	}

	return fmt.Sprintf("%.1f %s", fSize, units[unitIdx])
}

func runTUI(rootItem *Item) {
