	summarize        bool
	si               bool
	noPrefix         bool
	nonInteractive   bool
	versionFlag      bool
	noColor          bool
	noUnicode        bool
    sortBy           = "size"
    ignoreDirs       = "/proc,/dev,/sys,/run"
    maxDepth         int
    topItems         int
    sem              = make(chan struct{}, 64)
