	info, err := os.Lstat(absPath)
	if err != nil {
		return &Item{Name: filepath.Base(path), Path: absPath, Error: err}
	}

	item := &Item{
		Name:  info.Name(),
		Path:  absPath,
		IsDir: info.IsDir(),
		MTime: info.ModTime(),
	}

	stat, ok := info.Sys().(*syscall.Stat_t)
	if ok {
		item.Size = int64(stat.Blocks) * 512
        if item.IsDir && item.Size < 4096 { item.Size = 4096 }
	} else {
		item.Size = info.Size()
	}
	item.ASize = info.Size()

	if info.IsDir() {
		files, err := os.ReadDir(absPath)
		if err != nil {
			item.Error = err
			return item
		}
		if len(files) == 0 {
			item.IsEmpty = true
		}

        var mu sync.Mutex
        var wg sync.WaitGroup
        ignoreList := strings.Split(ignoreDirs, ",")
		for _, f := range files {
