		if showApparentSize { size = child.ASize }
        sizeStr := formatSize(size)
        if !noColor { sizeStr = "\033[33;1m" + sizeStr + "\033[0m" }
		fmt.Printf("%s%9s %s\n", prefix, sizeStr, name)
	}
}

func printItemRecursive(item *Item, currentDepth int) {
    if currentDepth > maxDepth { return }
    size := item.Size
    if showApparentSize { size = item.ASize }
    fmt.Printf("%8s %s\n", formatSize(size), item.Path)
    if currentDepth < maxDepth {
        sortItems(item.Children, "size")
        for _, child := range item.Children { printItemRecursive(child, currentDepth+1) }
    }
