    sort.Slice(items, func(i, j int) bool {
        switch by {
        case "name": return items[i].Name < items[j].Name
        case "itemCount": return items[i].ItemCount > items[j].ItemCount
        case "mtime": return items[i].MTime.After(items[j].MTime)
        default:
            s1, s2 := items[i].Size, items[j].Size
