    sortBy           = "size"
    ignoreDirs       = "/proc,/dev,/sys,/run"
    maxDepth         int
    topItems         int
    sem              = make(chan struct{}, 64)
    showHelp         bool
)

func main() {
	flag.BoolVar(&nonInteractive, "n", false, "Do not run in interactive mode")
	flag.BoolVar(&showApparentSize, "a", false, "Show apparent size")
	flag.BoolVar(&summarize, "s", false, "Show only a total in non-interactive mode")
	flag.BoolVar(&si, "si", false, "Show sizes with decimal SI prefixes")
	flag.BoolVar(&noPrefix, "no-prefix", false, "Show sizes as raw numbers")
	flag.BoolVar(&versionFlag, "version", false, "Print version")
	flag.BoolVar(&versionFlag, "v", false, "Print version")
	flag.BoolVar(&noColor, "c", false, "Do not use colorized output")
	flag.BoolVar(&noUnicode, "u", false, "Do not use Unicode symbols")
    flag.StringVar(&ignoreDirs, "i", "/proc,/dev,/sys,/run", "Paths to ignore")
    flag.IntVar(&maxDepth, "depth", 0, "Show directory structure up to specified depth")
    flag.IntVar(&topItems, "t", 0, "Show only top X largest files")
	flag.Parse()

	if versionFlag {
		fmt.Println("Version:\t dev")
		fmt.Println("Built time:\t Fri Apr 17 19:59:35 UTC 2026")
		fmt.Println("Built user:\t root")
		return
	}

	path := "."
	if flag.NArg() > 0 {
		path = flag.Arg(0)
	}

    if !nonInteractive && !isTerminal() {
        nonInteractive = true
    }

	item := scanPath(path)

	if nonInteractive {
        if topItems > 0 {
            printTopItems(item)
        } else if maxDepth > 0 {
            printItemRecursive(item, 0)
        } else {
		    printItem(item)
        }
	} else {
		runTUI(item)
	}
}

func isTerminal() bool {
    fi, _ := os.Stdin.Stat()
    return (fi.Mode() & os.ModeCharDevice) != 0
}

func scanPath(path string) *Item {
	absPath, _ := filepath.Abs(path)
	info, err := os.Lstat(absPath)
	if err != nil {
		return &Item{Name: filepath.Base(path), Path: absPath, Error: err}
	}

	item := &Item{
		Name:  info.Name(),
		Path:  absPath,
		IsDir: info.IsDir(),
		MTime: info.ModTime(),
	}

	stat, ok := info.Sys().(*syscall.Stat_t)
	if ok {
		item.Size = int64(stat.Blocks) * 512
        if item.IsDir && item.Size < 4096 { item.Size = 4096 }
	} else {
		item.Size = info.Size()
	}
	item.ASize = info.Size()

	if info.IsDir() {
		files, err := os.ReadDir(absPath)
		if err != nil {
			item.Error = err
			return item
		}
		if len(files) == 0 {
			item.IsEmpty = true
		}

        var mu sync.Mutex
        var wg sync.WaitGroup
        ignoreList := strings.Split(ignoreDirs, ",")
		for _, f := range files {
            childPath := filepath.Join(absPath, f.Name())
            ignored := false
            for _, i := range ignoreList {
                if childPath == i { ignored = true; break }
            }
            if ignored { continue }

            wg.Add(1)
            go func(cp string) {
                defer wg.Done()
                sem <- struct{}{}
                childItem := scanPath(cp)
                <-sem
                mu.Lock()
                childItem.Parent = item
                item.Children = append(item.Children, childItem)
                item.Size += childItem.Size
                item.ASize += childItem.ASize
                item.ItemCount += childItem.ItemCount
                if childItem.SubError || childItem.Error != nil {
                    item.SubError = true
                }
                mu.Unlock()
            }(childPath)
		}
        wg.Wait()
        item.ItemCount += 1
	} else {
		item.IsSymlink = info.Mode()&os.ModeSymlink != 0
		item.ItemCount = 1
	}

	return item
}

func printItem(item *Item) {
	if summarize {
		fmt.Printf("%8s %s\n", formatSize(item.Size), filepath.Base(item.Path))
		return
	}
	sortItems(item.Children, sortBy)
	for _, child := range item.Children {
		prefix := "  "
		if child.Error != nil { prefix = "! " } else if child.SubError { prefix = ". " } else if child.IsEmpty { prefix = "e " } else if child.IsSymlink { prefix = "@ " }
		name := child.Name
        dirColor, resetColor := "", ""
        if !noColor {
            if child.IsDir { dirColor = "\033[34;1m"; resetColor = "\033[0m" }
        }
		if child.IsDir { name = dirColor + "/" + name + resetColor }
		size := child.Size
		if showApparentSize { size = child.ASize }
        sizeStr := formatSize(size)
        if !noColor { sizeStr = "\033[33;1m" + sizeStr + "\033[0m" }
		fmt.Printf("%s%9s %s\n", prefix, sizeStr, name)
	}
}

func printItemRecursive(item *Item, currentDepth int) {
    if currentDepth > maxDepth { return }
    size := item.Size
    if showApparentSize { size = item.ASize }
    fmt.Printf("%8s %s\n", formatSize(size), item.Path)
    if currentDepth < maxDepth {
        sortItems(item.Children, "size")
        for _, child := range item.Children { printItemRecursive(child, currentDepth+1) }
    }
}

func printTopItems(item *Item) {
    var allFiles []*Item
    var collect func(*Item)
    collect = func(it *Item) {
        if !it.IsDir { allFiles = append(allFiles, it) }
        for _, child := range it.Children { collect(child) }
    }
    collect(item)
    sortItems(allFiles, "size")
    for i := 0; i < topItems && i < len(allFiles); i++ {
        size := allFiles[i].Size
        if showApparentSize { size = allFiles[i].ASize }
        fmt.Printf("%8s %s\n", formatSize(size), allFiles[i].Path)
    }
}

func sortItems(items []*Item, by string) {
    sort.Slice(items, func(i, j int) bool {
        switch by {
        case "name": return items[i].Name < items[j].Name
        case "itemCount": return items[i].ItemCount > items[j].ItemCount
        case "mtime": return items[i].MTime.After(items[j].MTime)
        default:
            s1, s2 := items[i].Size, items[j].Size
            if showApparentSize { s1, s2 = items[i].ASize, items[j].ASize }
            if s1 == s2 { return items[i].Name < items[j].Name }
            return s1 > s2
        }
    })
}

func formatSize(size int64) string {
	if noPrefix { return fmt.Sprintf("%d", size) }
	var units []string
	var base float64
	if si { units = []string{"B", "kB", "MB", "GB", "TB", "PB"}; base = 1000 } else { units = []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB"}; base = 1024 }
	if size < int64(base) && size >= 0 { return fmt.Sprintf("%d B", size) }
	fSize := float64(size)
	unitIdx := 0
	for fSize >= base && unitIdx < len(units)-1 { fSize /= base; unitIdx++ }
	return fmt.Sprintf("%5.1f %s", fSize, units[unitIdx])
}

func runTUI(rootItem *Item) {
    exec.Command("stty", "-F", "/dev/tty", "cbreak", "min", "1").Run()
    exec.Command("stty", "-F", "/dev/tty", "-echo").Run()
    defer exec.Command("stty", "-F", "/dev/tty", "sane").Run()
    currentItem, selectedIndex := rootItem, 0
    for {
        draw(currentItem, selectedIndex)
        var b [1]byte
        os.Stdin.Read(b[:])
        if showHelp { showHelp = false; continue }
        switch b[0] {
        case 'q', 'Q': return
        case 'j': if selectedIndex < len(currentItem.Children)-1 { selectedIndex++ }
        case 'k': if selectedIndex > 0 { selectedIndex-- }
        case 'h':
            if currentItem.Parent != nil {
                name := currentItem.Name
                currentItem = currentItem.Parent
                for i, c := range currentItem.Children { if c.Name == name { selectedIndex = i; break } }
            }
        case 'l', 13:
            if len(currentItem.Children) > 0 && currentItem.Children[selectedIndex].IsDir {
                currentItem = currentItem.Children[selectedIndex]; selectedIndex = 0
            }
        case 'a': showApparentSize = !showApparentSize
        case 'n': sortBy = "name"
        case 's': sortBy = "size"
        case 'c': sortBy = "itemCount"
        case 'm': sortBy = "mtime"
        case '?': showHelp = true
        case 27:
            var b2 [2]byte
            os.Stdin.Read(b2[:])
            if b2[0] == '[' {
                switch b2[1] {
                case 'A': if selectedIndex > 0 { selectedIndex-- }
                case 'B': if selectedIndex < len(currentItem.Children)-1 { selectedIndex++ }
                }
            }
        }
    }
}

func draw(item *Item, selectedIndex int) {
    fmt.Print("\033[H\033[2J")
    if showHelp {
        fmt.Println("Help screen...") // Simplified help
        return
    }
    fmt.Printf(" gdu ~ Use arrow keys to navigate, press ? for help\n")
    fmt.Printf(" --- %s ---\n", item.Path)
    if item.Parent != nil { fmt.Printf("                         /..\n") }
    sortItems(item.Children, sortBy)
    for i, child := range item.Children {
        cursor := "  "
        if i == selectedIndex { cursor = "> " }
        name := child.Name
        if child.IsDir { name = "/" + name }
        size := child.Size
        if showApparentSize { size = child.ASize }
        bar := drawBar(float64(size) / float64(item.Size))
        fmt.Printf("%s%9s %s %s\n", cursor, formatSize(size), bar, name)
    }
    fmt.Printf("\n Total disk usage: %s Apparent size: %s Items: %d Sorting by: %s\n",
        formatSize(item.Size), formatSize(item.ASize), item.ItemCount, sortBy)
}

func drawBar(percent float64) string {
    if noUnicode {
        res := "["
        for i := 0; i < 10; i++ { if float64(i) < percent*10 { res += "#" } else { res += " " } }
        return res + "]"
    }
    blocks := []string{" ", "▏", "▎", "▍", "▌", "▋", "▊", "▉", "█"}
    res := ""
    fullBlocks := int(percent * 10)
    for i := 0; i < fullBlocks; i++ { res += "█" }
    if fullBlocks < 10 {
        res += blocks[int((percent*10-float64(fullBlocks))*8)]
        for i := fullBlocks + 1; i < 10; i++ { res += " " }
    }
    return res + "▏"
}
